SELECT COALESCE(
			   (SELECT o.price FROM stock_transactions t
										JOIN orders o ON t.buy_order_id = o.order_id WHERE o.stock_id = #{stockId}
		        ORDER BY t.created_date DESC LIMIT 1),
		       (SELECT publication_price FROM stocks WHERE stock_id = #{stockId})
       )

SELECT order_id FROM orders
WHERE content = #{content} AND (student_id = #{studentId} OR student_id = (SELECT CAST(id AS CHAR) FROM students WHERE student_id = #{studentId} LIMIT 1)) AND stock_id = #{stockId}
AND state = #{state} AND amount = #{amount} AND price = #{price} ORDER BY created_date DESC LIMIT 1

SELECT o.order_id, o.content, o.price, o.amount, o.state, o.created_date, COALESCE(s.student_id, o.student_id) AS student_id, o.stock_id
FROM orders o
LEFT JOIN students s ON (o.student_id = CAST(s.id AS CHAR) OR o.student_id = s.student_id)
WHERE o.stock_id = #{stockId}
  AND o.state IN ('대기', 'WAITING')
  AND o.content = #{content}
  AND o.price = #{orderPrice}
  AND COALESCE(s.student_id, o.student_id) != #{studentId}
ORDER BY created_date ASC
	FOR UPDATE

